+/* Debug-mode writes: restore saved vl/vtype (used by hybrid gdbstub handback).
+ * vill is packed in the MSB of the architectural vtype register. */
+static RISCVException write_vl(CPURISCVState *env, int csrno,
+                               target_ulong val)
+{
+    env->vl = val;
+    return RISCV_EXCP_NONE;
+}
+
+static RISCVException write_vtype(CPURISCVState *env, int csrno,
+                                  target_ulong val)
+{
+    switch (env->xl) {
+    case MXL_RV32:
+        env->vill  = (val >> 31) & 1;
+        env->vtype = val & ~(target_ulong)(1u << 31);
+        break;
+    case MXL_RV64:
+        env->vill  = (val >> 63) & 1;
+        env->vtype = val & ~(uint64_t)(1ULL << 63);
+        break;
+    default:
+        g_assert_not_reached();
+    }
+    return RISCV_EXCP_NONE;
+}
